def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = []
    prev_bids = []
    opp_pressure = 0.0
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                b = float(prev['bid'])
                prev_bids.append(b)
                req = float(opp.get('water_requirement', WATER_REQ))
                sal = float(opp.get('daily_salary', DAILY_SALARY))
                urgency = 1.0
                if opp.get('hp', 10) <= 4 or opp.get('no_water_days', 0) >= 1:
                    urgency = 1.2
                opp_pressure = max(opp_pressure, b / max(1.0, sal) * urgency * (req / float(WATER_REQ)))

    if budget <= 0:
        return 0.0

    slots = supply / float(WATER_REQ)
    scarcity = 0
    if slots <= 1.05:
        scarcity = 3
    elif slots <= 1.6:
        scarcity = 2
    elif slots <= 2.1:
        scarcity = 1

    my_urgency = 0
    if hp <= 2 or no_water >= 2:
        my_urgency = 3
    elif hp <= 4 or no_water >= 1:
        my_urgency = 2
    elif hp <= 6:
        my_urgency = 1

    if not alive:
        base = DAILY_SALARY * 0.22
        if my_urgency >= 2:
            base = DAILY_SALARY * 0.55
        return max(0.0, min(float(budget), float(base)))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    if scarcity == 0:
        bid = DAILY_SALARY * 0.18
        if my_urgency >= 2:
            bid = max(bid, DAILY_SALARY * 0.42)
        if highest_prev > 0 and my_urgency >= 1:
            bid = max(bid, min(highest_prev * 0.55, DAILY_SALARY * 0.7))
    elif scarcity == 1:
        bid = DAILY_SALARY * 0.38
        if highest_prev > 0:
            bid = max(bid, min(highest_prev + 2.0, DAILY_SALARY * 0.95))
        if my_urgency >= 2:
            bid = max(bid, DAILY_SALARY * 0.78)
    elif scarcity == 2:
        bid = DAILY_SALARY * 0.62
        if highest_prev > 0:
            bid = max(bid, min(highest_prev + 4.0, DAILY_SALARY * 1.2))
        if my_urgency >= 2:
            bid = max(bid, DAILY_SALARY * 0.95)
        if opp_pressure > 1.8:
            bid = max(bid, DAILY_SALARY * 1.05)
    else:
        bid = DAILY_SALARY * 0.9
        if highest_prev > 0:
            bid = max(bid, min(highest_prev + 6.0, DAILY_SALARY * 1.45))
        if my_urgency >= 2:
            bid = max(bid, DAILY_SALARY * 1.15)
        if opp_pressure > 2.0:
            bid = max(bid, DAILY_SALARY * 1.25)

    if day >= 8 and hp >= 7 and scarcity <= 1:
        bid *= 0.82

    if budget < DAILY_SALARY * 1.2:
        bid = min(bid, budget * 0.72)
    elif budget < DAILY_SALARY * 2.5:
        bid = min(bid, budget * 0.8)

    if my_urgency == 0 and avg_prev >= DAILY_SALARY * 1.8 and scarcity <= 1:
        bid = min(bid, DAILY_SALARY * 0.28)

    bid = max(0.0, min(float(budget), float(bid)))
    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    hp = int(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = [o for o in opponents_status.values() if o.get('alive', False)]
    if not alive_opps:
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    yesterday_bids = []
    for opp in alive_opps:
        prev = opp.get('previous_trace', {})
        if isinstance(prev, dict):
            b = prev.get('bid', None)
            if b is not None:
                try:
                    yesterday_bids.append(float(b))
                except Exception:
                    pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    # Estimate how many rounds of water we can buy at minimum effective intensity.
    # (We don't know exact mapping from bid->water, but use supply to scale aggressiveness.)
    supply_factor = 0.5
    if supply >= 21.0:
        supply_factor = 0.85
    elif supply <= 17.0:
        supply_factor = 0.65

    # Pressure detection: if someone bid near our daily salary, they likely enforced a high-water contest.
    pressure = 0.0
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        pressure = 1.0
    elif highest_prev_bid >= DAILY_SALARY * 0.6:
        pressure = 0.6
    elif highest_prev_bid >= DAILY_SALARY * 0.35:
        pressure = 0.35

    # Core strategy: bid enough to avoid falling behind, but don't overpay when HP is safe.
    if hp <= 2 or no_water_days >= 2:
        # Emergency ramp: protect survival.
        target = DAILY_SALARY * (0.75 + 0.15 * pressure) * supply_factor
    elif hp <= 4:
        target = DAILY_SALARY * (0.55 + 0.20 * pressure) * supply_factor
    else:
        # Healthy: stay competitive but cheaper.
        target = DAILY_SALARY * (0.45 + 0.15 * pressure) * supply_factor

    # If yesterday pressure was very high, slightly undercut to still be competitive.
    if highest_prev_bid > 0.0 and pressure >= 0.6:
        target = min(target, highest_prev_bid + 5.0)

    # Clamp to budget and non-negative.
    bid = max(0.0, min(budget, target))

    # Avoid bidding absurdly high when budget is tiny.
    if budget < DAILY_SALARY * 0.2:
        bid = min(bid, budget)

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    MAX_SUPPLY = 25
